python3 - <<'PY'
for path,names in [('src/Surface.zig',['keyCallback','mouseButtonCallback','performBindingAction','updateConfig','sizeCallback','childExited']),('src/renderer/generic.zig',['Renderer','updateFrame','drawFrame']),('src/termio/Exec.zig',['queueWrite','threadExit','initTerminal'])]:
 s=open(path).readlines();import re
 for name in names:
  matches=[i for i,l in enumerate(s) if re.match(r'\s*(pub )?fn '+name+r'\b',l)]
  for i in matches[:2]:
   depth=0;started=False
   for j in range(i,len(s)):
    for c in s[j]:
     if c=='{':depth+=1;started=True
     if c=='}':depth-=1
    if started and depth==0:break
   print(path,name,i+1,j+1)
PY

